expressionFragments.discarded-short-circuit:
precision mediump float;
uniform bool gate;
float calls;
bool left() { calls += 1.; return gate; }
bool right() { calls += 2.; return true; }
void main() {
  calls = 0.;
  if (!gate) left() && right();
  if (!gate) left() || right();
  for (int i = 0; i < 2; ++i) left() && right();
  if (gate) right();
  gl_FragColor = calls == 6. ? vec4(0.,1.,0.,1.) : vec4(1.,0.,0.,1.);
}

expressionFragments.conditional-function-return:
precision mediump float;
uniform float offset;
vec2 choose(float f) { if (f > 0.) return vec2(-f, f + 1.); }
void main() {
  vec2 result = choose(2. + offset);
  gl_FragColor = result == vec2(-2., 3.) ? vec4(0.,1.,0.,1.) : vec4(1.,0.,0.,1.);
}

expressionFragments.component-assignment-result:
precision mediump float;
float calls;
vec3 globalValue;
float one() { calls += 1.; return 1.; }
vec3 chain() {
  vec3 local = vec3(0., 0., 7.);
  local.x = local.y = one();
  float later = (local.y += 2.);
  return vec3(local.x, later, local.z);
}
void main() {
  calls = 0.;
  globalValue = vec3(1., 2., 3.);
  float assigned = (globalValue.z = one());
  float nested = (globalValue.x = (globalValue.y = one()));
  float indexed = 0.;
  for (int lane = 0; lane < 1; ++lane) indexed = (globalValue[lane] += one());
  float previous = globalValue.z++;
  float incremented = ++globalValue.y;
  bool valid = nested == 1. && indexed == 2. && previous == 1. && incremented == 2. && chain() == vec3(1., 3., 7.) && assigned == 1. && calls == 4.;
  valid = valid && globalValue == vec3(2., 2., 2.);
  gl_FragColor = valid ? vec4(0.,1.,0.,1.) : vec4(1.,0.,0.,1.);
}
